def _stamp_existing_sequences(apps, schema_editor):
    """Existing counters were yearly, so put them in this year's bucket.

    Without this an installation upgrading mid-year would start again at 1
    and issue numbers that were already used this year.
    """
    NumberSequence = apps.get_model("core", "NumberSequence")
    NumberSequence.objects.filter(year=0).update(year=timezone.localdate().year)


